/* ============================================================
   DEDSEC-STYLE THEME v2 for Stylish
   Matte black / dark gunmetal / silver / subtle electric blue
   Paste into a style set to "Apply to: all URLs"
   ============================================================ */
/* ---------- 1. COLOUR PALETTE (change these to retheme) ---------- */
:root {
  --ds-bg:       #0b0b0d;   /* matte black */
  --ds-gunmetal: #1b2026;   /* dark gunmetal */
  --ds-steel:    #2c333b;   /* lighter gunmetal for thumbs/lines */
  --ds-silver:   #c3c9d0;   /* silver text */
  --ds-blue:     #2f8fff;   /* electric blue accent */
}

/* ---------- 2. BASE LOOK ---------- */
html, body {
  background-color: var(--ds-bg) !important;
  color: var(--ds-silver) !important;
  font-family: 'Share Tech Mono', monospace !important;
}

/* faint pixel grid */
body {
  background-image:
    linear-gradient(rgba(47,143,255,0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(47,143,255,0.035) 1px, transparent 1px) !important;
  background-size: 8px 8px !important;
}

/* pixel-style headings: silver with a soft blue glow */
h1, h2, h3, h4 {
  font-family: 'VT323', monospace !important;
  color: #e2e6ea !important;
  letter-spacing: 1px;
  text-shadow: 0 0 6px rgba(47,143,255,0.55);
}

/* ---------- 3. LINKS ---------- */
a, a:visited { color: var(--ds-blue) !important; text-decoration: none !important; }
a:hover {
  color: #e2e6ea !important;
  text-shadow: 0 0 6px rgba(47,143,255,0.8);
}

/* ---------- 4. TEXT SELECTION ---------- */
::selection { background: var(--ds-blue); color: #000; }

/* ---------- 5. SCROLLBAR ---------- */
::-webkit-scrollbar { width: 12px; height: 12px; background: var(--ds-bg); }
::-webkit-scrollbar-thumb { background: var(--ds-steel); border: 2px solid var(--ds-bg); }
::-webkit-scrollbar-thumb:hover { background: var(--ds-blue); }

/* ---------- 6. CRT SCANLINES OVERLAY ---------- */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;      /* never blocks clicks */
  z-index: 2147483646;
  background: repeating-linear-gradient(
    to bottom,
    rgba(0,0,0,0) 0px,
    rgba(0,0,0,0) 2px,
    rgba(0,0,0,0.18) 3px
  );
}

/* ---------- 7. SUBTLE GLITCH ON IMAGE HOVER ---------- */
@keyframes ds-glitch {
  0%   { transform: translate(0, 0); }
  25%  { transform: translate(-2px, 1px); }
  50%  { transform: translate(2px, -1px); }
  75%  { transform: translate(-1px, -1px); }
  100% { transform: translate(0, 0); }
}
img:hover { animation: ds-glitch 0.25s steps(2) 2; }
